<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Pterodactyl\Services\Dezerx\Editor; use Pterodactyl\Services\Dezerx\Theme; use Pterodactyl\Services\Dezerx\Appearance; use Pterodactyl\Services\Dezerx\Uploads; use Pterodactyl\Services\Dezerx\Settings; use Pterodactyl\Http\Controllers\Controller; class EditorController extends Controller { public function index(): JsonResponse { return new JsonResponse(Editor::payload()); } public function update(Request $request): JsonResponse { $theme = Theme::sanitise((array) $request->input('theme', [])); Settings::put(Theme::SETTING_KEY, $theme); return new JsonResponse(['theme' => $theme]); } public function reset(): JsonResponse { Settings::forget(Theme::SETTING_KEY); Settings::put( Appearance::SETTING_KEY, array_replace(Settings::get(Appearance::SETTING_KEY) ?? [], [ 'tokens' => ['dark' => [], 'light' => []], 'fonts' => Appearance::FONT_DEFAULTS, ]), ); return new JsonResponse([ 'theme' => Theme::defaults(), 'appearance' => Appearance::payload() + ['tokens' => Appearance::tokens()], ]); } public const EXPORT_FORMAT = 'dezerx-stark-theme'; public const EXPORT_VERSION = 1; public function export(): JsonResponse { $appearance = Settings::get(Appearance::SETTING_KEY) ?? []; return new JsonResponse([ 'format' => self::EXPORT_FORMAT, 'version' => self::EXPORT_VERSION, 'exportedAt' => now()->toIso8601String(), 'panel' => config('app.url'), 'theme' => Theme::config(), 'appearance' => [ 'tokens' => Appearance::tokens(), 'fonts' => Appearance::fonts(), 'logo' => Appearance::logo(), 'presets' => Appearance::presets(), 'defaultPreset' => (string) ($appearance['defaultPreset'] ?? 'default'), 'allowUserPresets' => Appearance::allowUserPresets(), ], ]); } public function import(Request $request): JsonResponse { $format = (string) $request->input('format', ''); if ($format !== self::EXPORT_FORMAT) { return new JsonResponse(['errors' => [['code' => 'NotATheme', 'status' => '422', 'detail' => 'That file is not a Stark theme export.']]], 422); } if ((int) $request->input('version', 0) > self::EXPORT_VERSION) { return new JsonResponse(['errors' => [['code' => 'TooNew', 'status' => '422', 'detail' => 'That file was written by a newer panel than this one.']]], 422); } $applied = []; if (is_array($request->input('theme'))) { Settings::put(Theme::SETTING_KEY, Theme::sanitise((array) $request->input('theme'))); $applied[] = 'theme'; } $appearance = $request->input('appearance'); if (is_array($appearance)) { $patch = []; if (is_array($appearance['tokens'] ?? null)) { $patch['tokens'] = [ 'dark' => Appearance::sanitiseTokens($appearance['tokens']['dark'] ?? []), 'light' => Appearance::sanitiseTokens($appearance['tokens']['light'] ?? []), ]; $applied[] = 'colours'; } if (is_array($appearance['fonts'] ?? null)) { $fonts = []; foreach (Appearance::FONT_SLOTS as $slot) { $fonts[$slot] = Appearance::fontForSlot($appearance['fonts'][$slot] ?? null, $slot); } $patch['fonts'] = $fonts; $applied[] = 'fonts'; } if (is_array($appearance['presets'] ?? null)) { $presets = Appearance::sanitisePresets((array) $appearance['presets']); $ids = array_column($presets, 'id'); $default = Appearance::slug((string) ($appearance['defaultPreset'] ?? '')); $patch['presets'] = $presets; $patch['defaultPreset'] = in_array($default, $ids, true) ? $default : ($ids[0] ?? 'default'); $patch['allowUserPresets'] = (bool) ($appearance['allowUserPresets'] ?? true); $applied[] = 'palettes'; } if (is_array($appearance['logo'] ?? null)) { $logo = $appearance['logo']; $image = Appearance::path($logo['image'] ?? null); $mark = Appearance::path($logo['mark'] ?? null); $mode = (string) ($logo['mode'] ?? 'text'); if ($mode === 'text' || $image !== '' || $mark !== '') { $patch['logo'] = [ 'mode' => in_array($mode, Appearance::LOGO_MODES, true) ? $mode : 'text', 'text' => mb_substr(trim((string) ($logo['text'] ?? '')), 0, 40), 'image' => $image, 'imageLight' => Appearance::path($logo['imageLight'] ?? null), 'mark' => $mark === '' ? null : $mark, 'alt' => mb_substr(trim((string) ($logo['alt'] ?? '')), 0, 80), ]; $applied[] = 'logo'; } } if ($patch !== []) { Settings::put(Appearance::SETTING_KEY, array_replace(Settings::get(Appearance::SETTING_KEY) ?? [], $patch)); } } if ($applied === []) { return new JsonResponse(['errors' => [['code' => 'NothingToApply', 'status' => '422', 'detail' => 'That file had nothing in it this panel could use.']]], 422); } return new JsonResponse([ 'applied' => $applied, 'theme' => Theme::config(), 'appearance' => Appearance::payload() + ['tokens' => Appearance::tokens()], ]); } public function background(Request $request): JsonResponse { return new JsonResponse(['path' => Uploads::store($request, 'backgrounds')]); } } 